'use client';

/**
 * <RoxyEndpointForm data={...} /> — Schema-driven form that emits roxy-submit with a validated payload.
 *
 * You own this file. Customize freely. The underlying Lit element loads
 * from jsDelivr at runtime via @roxyapi/ui-react, so updates ship without
 * a re-install.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/endpoint-form/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   // <RoxyEndpointForm> introspects the OpenAPI spec at runtime — no
   *   // server route needed unless you want to proxy the form submission.
   *   const values = await req.json();
   *   const { data } = await fetch(\`https://roxyapi.com/api/v2/\${endpoint}\`, { ...values });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyEndpointForm as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyEndpointFormProps = ComponentProps<typeof Element>;

export function RoxyEndpointForm(props: RoxyEndpointFormProps) {
	return <Element {...props} />;
}

export default RoxyEndpointForm;
